import sys, inspect; sys.path.insert(0, sys.argv[1])
from boltons import funcutils as F
def chk(f, *a, **k):
    @F.wraps(f)
    def w(*aa, **kk): return f(*aa, **kk)
    try:
        s1, s2 = str(inspect.signature(f)), str(inspect.signature(w))
        res = (w(*a, **k), f(*a, **k))
        print('OK ' if s1==s2 and res[0]==res[1] else 'BAD', s1, '|', s2, res)
    except Exception as e: print('EXC', inspect.signature(f), repr(e))
exec('''
def p1(a, b=1, /, c=2, *, d=3): return (a,b,c,d)
def p2(a, /, b, *args, c, **kw): return (a,b,args,c,kw)
def p3(a=1, b=2, *args): return (a,b,args)
def p4(a, b=2, *, c): return (a,b,c)
def p5(*, a=1, b): return (a,b)
def p6(a, /): return a
''')
chk(p1, 0); chk(p1, 0, 5, c=6, d=7); chk(p2, 1, 2, 3, c=4, z=5); chk(p3, 9, 8, 7); chk(p4, 1, c=3); chk(p5, b=2); chk(p6, 1)
fb = F.FunctionBuilder.from_func(p1); print(fb.get_sig_str(), fb.get_invocation_str())
fb = F.FunctionBuilder.from_func(p3); print(fb.get_sig_str(), fb.get_invocation_str())
fb = F.FunctionBuilder('f', args=['a','b'], defaults=(2,), body='return a+b'); print(fb.get_func()(1), fb.get_sig_str())
EOF
